1	package checkpoint
2	
3	import (
4		"context"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io/fs"
9		"os"
10		"path/filepath"
11		"slices"
12	
13		"github.com/go-git/go-git/v6"
14	
15		"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
16		"github.com/entireio/cli/cmd/entire/cli/gitdir"
17		"github.com/entireio/cli/cmd/entire/cli/internal/flock"
18		"github.com/entireio/cli/cmd/entire/cli/jsonutil"
19		"github.com/entireio/cli/cmd/entire/cli/osroot"
20	)
21	
22	// The deleted-checkpoints list lives in the git common dir beside the push
23	// queue, so every worktree of a clone sees the same answer. It records the IDs
24	// `entire checkpoint delete` removed so local writers that would otherwise
25	// re-create one (an amend restoring its Entire-Checkpoint trailer, a v1→refs
26	// migration reading a stale tracking ref) can decline. It is local-only: a
27	// precursor to remote tombstones, which would also stop other clones.
28	const (
29		deletedCheckpointsFileName = "entire-deleted-checkpoints.json"
30		deletedCheckpointsLockName = "entire-deleted-checkpoints.lock"
31	)
32	
33	// deletedCheckpointsFile stores plain strings so one malformed entry is
34	// skipped on read rather than failing id.CheckpointID's strict unmarshal for
35	// the whole list.
36	type deletedCheckpointsFile struct {
37		CheckpointIDs []string `json:"checkpoint_ids"`
38	}
39	
40	// DeletedCheckpointSet is a loaded deleted-checkpoints list.
41	type DeletedCheckpointSet map[id.CheckpointID]struct{}
42	
43	// Contains reports whether cid was deleted from this clone.
44	func (s DeletedCheckpointSet) Contains(cid id.CheckpointID) bool {
45		_, ok := s[cid]
46		return ok
47	}
48	
49	// DeletedCheckpoints is the flock-protected list of checkpoint IDs deleted
50	// from this clone.
51	type DeletedCheckpoints struct {
52		dir string
53	}
54	
55	// NewDeletedCheckpoints returns the list stored in gitCommonDir.
56	func NewDeletedCheckpoints(gitCommonDir string) *DeletedCheckpoints {
57		return &DeletedCheckpoints{dir: gitCommonDir}
58	}
59	
60	// DeletedCheckpointsForRepo resolves repo's git common dir and returns its list.
61	func DeletedCheckpointsForRepo(repo *git.Repository) (*DeletedCheckpoints, error) {
62		_, dir, err := repositoryDirs(repo)
63		if err != nil {
64			return nil, fmt.Errorf("resolve git common dir for deleted checkpoints: %w", err)
65		}
66		return NewDeletedCheckpoints(dir), nil
67	}
68	
69	// LoadDeletedCheckpoints reads the list for the repository ctx resolves to.
70	// Callers on hook paths treat an error as "nothing deleted": the list only
71	// narrows what a hook writes, so failing open keeps the hook working.
72	func LoadDeletedCheckpoints(ctx context.Context) (DeletedCheckpointSet, error) {
73		dir, err := gitdir.CommonDir(ctx)
74		if err != nil {
75			return nil, fmt.Errorf("resolve git common dir for deleted checkpoints: %w", err)
76		}
77		return NewDeletedCheckpoints(dir).Load()
78	}
79	
80	func loadDeletedForRepo(repo *git.Repository) (DeletedCheckpointSet, error) {
81		list, err := DeletedCheckpointsForRepo(repo)
82		if err != nil {
83			return nil, err
84		}
85		return list.Load()
86	}
87	
88	// Record adds cid to the list. Recording an ID already present is a no-op.
89	func (d *DeletedCheckpoints) Record(cid id.CheckpointID) error {
90		_, err := d.Add(cid)
91		return err
92	}
93	
94	// Add records cid and reports whether this call added it (false when it was
95	// already listed), so a caller that undoes its own record never removes an
96	// entry an earlier delete made.
97	func (d *DeletedCheckpoints) Add(cid id.CheckpointID) (bool, error) {
98		if cid.Kind() == id.KindUnknown {
99			return false, fmt.Errorf("record deleted checkpoint: invalid checkpoint ID %q", cid)
100		}
101		added := false
102		err := d.update(func(ids []id.CheckpointID) ([]id.CheckpointID, bool) {
103			if slices.Contains(ids, cid) {
104				return ids, false
105			}
106			added = true
107			return append(ids, cid), true
108		})
109		return added, err
110	}
111	
112	// Remove takes cid off the list again, for a delete that failed before it
113	// removed any copy. Removing an ID that is not listed is a no-op.
114	func (d *DeletedCheckpoints) Remove(cid id.CheckpointID) error {
115		return d.update(func(ids []id.CheckpointID) ([]id.CheckpointID, bool) {
116			if !slices.Contains(ids, cid) {
117				return ids, false
118			}
119			return slices.DeleteFunc(ids, func(recorded id.CheckpointID) bool { return recorded == cid }), true
120		})
121	}
122	
123	// update rewrites the list under its lock; change reports whether it altered
124	// the IDs, and an unchanged list is not rewritten.
125	func (d *DeletedCheckpoints) update(change func([]id.CheckpointID) ([]id.CheckpointID, bool)) error {
126		root, err := gitdir.OpenAt(d.dir)
127		if err != nil {
128			return fmt.Errorf("open git common dir: %w", err)
129		}
130		release, err := flock.AcquireIn(root, deletedCheckpointsLockName)
131		if err != nil {
132			return fmt.Errorf("lock deleted checkpoints list: %w", err)
133		}
134		defer release()
135	
136		ids, err := d.read(root)
137		if err != nil {
138			return err
139		}
140		ids, changed := change(ids)
141		if !changed {
142			return nil
143		}
144		raw := make([]string, len(ids))
145		for i, recorded := range ids {
146			raw[i] = recorded.String()
147		}
148		data, err := json.Marshal(deletedCheckpointsFile{CheckpointIDs: raw})
149		if err != nil {
150			return fmt.Errorf("encode deleted checkpoints list: %w", err)
151		}
152		if err := jsonutil.WriteFileAtomicIn(root, deletedCheckpointsFileName, data, 0o600); err != nil {
153			return fmt.Errorf("write deleted checkpoints list %s: %w", d.path(), err)
154		}
155		return nil
156	}
157	
158	// Load returns the recorded IDs. A missing file is an empty list; an
159	// unreadable or corrupt one is an error, never an empty list, so a damaged
160	// file cannot silently let a deleted checkpoint come back.
161	func (d *DeletedCheckpoints) Load() (DeletedCheckpointSet, error) {
162		root, err := gitdir.OpenAt(d.dir)
163		if err != nil {
164			return nil, fmt.Errorf("open git common dir: %w", err)
165		}
166		ids, err := d.read(root)
167		if err != nil {
168			return nil, err
169		}
170		set := make(DeletedCheckpointSet, len(ids))
171		for _, cid := range ids {
172			set[cid] = struct{}{}
173		}
174		return set, nil
175	}
176	
177	// path names the list file in errors, so a user can find the file to fix.
178	func (d *DeletedCheckpoints) path() string {
179		return filepath.Join(d.dir, deletedCheckpointsFileName)
180	}
181	
182	func (d *DeletedCheckpoints) read(root *os.Root) ([]id.CheckpointID, error) {
183		data, err := osroot.ReadFileNoFollow(root, deletedCheckpointsFileName)
184		if errors.Is(err, fs.ErrNotExist) {
185			return nil, nil
186		}
187		if err != nil {
188			return nil, fmt.Errorf("read deleted checkpoints list %s: %w", d.path(), err)
189		}
190		var file deletedCheckpointsFile
191		if err := json.Unmarshal(data, &file); err != nil {
192			return nil, fmt.Errorf("parse deleted checkpoints list %s: %w", d.path(), err)
193		}
194		valid := make([]id.CheckpointID, 0, len(file.CheckpointIDs))
195		for _, raw := range file.CheckpointIDs {
196			if cid, err := id.NewCheckpointID(raw); err == nil {
197				valid = append(valid, cid)
198			}
199		}
200		return valid, nil
201	}
202

