func fetchMetadataFromRemote(ctx context.Context, remoteName string, noFilter, advanceLocal bool) error {
	refs := checkpoint.ResolveRefs(ctx)
	if !refs.Primary.IsBranch() {
		return fmt.Errorf("primary metadata ref %s is not a branch", refs.Primary)
	}
	branchName := refs.Primary.Short()

	// Bounded by whichever is tighter: this candidate's own window, or what the
	// chain ceiling has left. The message below reports the effective deadline
	// rather than ReadFetchTimeout — a later candidate is often capped by the
	// remainder, and naming the wrong number misleads on exactly the path (an
	// unreachable elected remote) this is meant to make debuggable.
	budget := remote.ReadFetchTimeout
	if deadline, ok := ctx.Deadline(); ok {
		if remaining := time.Until(deadline); remaining < budget {
			budget = remaining
		}
	}
	ctx, cancel := context.WithTimeout(ctx, budget)
	defer cancel()

	fetchTarget, err := remote.ResolveFetchTarget(ctx, remoteName)
	if err != nil {
		return fmt.Errorf("failed to resolve fetch target: %w", err)
	}

	refSpec := fmt.Sprintf("+refs/heads/%s:refs/remotes/%s/%s", branchName, remoteName, branchName)

	_, fetchErr := remote.Fetch(ctx, remote.FetchOptions{
		Remote:   fetchTarget,
		RefSpecs: []string{refSpec},
		NoTags:   true,
		NoFilter: noFilter,
		// Heal a repo that an older CLI already shallowed with --depth=1: the
		// metadata tip is grafted in .git/shallow, which breaks merge-base
		// connectivity checks for the metadata branch. A ref-scoped deep fetch
		// removes that boundary without deepening an independently-shallow
		// source-tree clone (unlike --unshallow), and is a no-op on a normally
		// cloned repo.
		Depth: metadataFetchDepth,
	})
	if fetchErr != nil {
		if ctx.Err() == context.DeadlineExceeded {
			return fmt.Errorf("fetch timed out after %s", budget.Round(time.Second))
		}
		return formatFilteredFetchError("failed to fetch "+branchName, fetchTarget, fetchErr)
	}

	repo, err := openRepository(ctx)
	if err != nil {
		return fmt.Errorf("failed to open repository: %w", err)
	}
	defer repo.Close()

	remoteRef, err := repo.Reference(plumbing.NewRemoteReferenceName(remoteName, branchName), true)
	if err != nil {
		return fmt.Errorf("branch '%s' not found on %s: %w", branchName, remoteName, err)
	}
	if !advanceLocal {
		// Legacy read tier: the fetched data is readable through the tracking
		// ref, but the local primary is never advanced from it.
		return nil
	}
	if err := strategy.SafelyAdvanceLocalRef(ctx, repo, refs.Primary, remoteRef.Hash()); err != nil {
		return fmt.Errorf("failed to advance local %s branch: %w", branchName, err)
	}
	return nil
}

// FetchMetadataFromCheckpointRemote fetches the entire/checkpoints/v1 branch from the
// configured checkpoint_remote URL and updates the local branch.
// Returns an error if the fetch fails or no checkpoint_remote is configured.
func FetchMetadataFromCheckpointRemote(ctx context.Context) error {
func FetchMetadataBranch(ctx context.Context, remoteURL string) error {
	return fetchMetadataBranchWithin(ctx, remoteURL, foregroundFetch)
}

func fetchMetadataBranchWithin(ctx context.Context, remoteURL string, mode checkpointFetchMode) error {
	refs := checkpoint.ResolveRefs(ctx)
	if !refs.Primary.IsBranch() {
		return fmt.Errorf("primary metadata ref %s is not a branch", refs.Primary)
	}
	branchName := refs.Primary.Short()
	tmpRef := FetchTmpRefPrefix + branchName
	if mode == hotPathFetch {
		// The hot path skips the fetch lock rather than stall a push behind a
		// long foreground fetch, so it must not share that fetch's tmp ref.
		tmpRef = FetchTmpRefPrefix + "push/" + branchName
	}
	srcRef := refs.Primary.String()

	fetchCtx := ctx
	if mode == foregroundFetch {
		var release func()
		var err error
		fetchCtx, release, err = startForegroundFetch(ctx, "")
		if err != nil {
			return err
		}
		defer release()
	}
	if err := fetchURLIntoTmpRef(fetchCtx, "", remoteURL, srcRef, tmpRef, "metadata branch", true, mode); err != nil {
		return err
	}
	if err := PromoteTmpRefSafely(ctx, plumbing.ReferenceName(tmpRef), refs.Primary, branchName); err != nil {
		return err
	}

	return nil
}

// fetchURLIntoTmpRef runs `git fetch <remoteURL> +<srcRef>:<tmpRef>` via the
// checkpoint git wrapper, disabling the terminal prompt so a misconfigured
// credential helper doesn't hang the process. Errors include the redacted URL
// and any captured stderr so operators can diagnose without credentials
// leaking into logs.
//
// When noFilter is true, --filter=blob:none is suppressed even if filtered
// fetches are globally enabled. v1's blobs are the full transcript archive, so
// an unfiltered fetch costs the whole history where a filtered one costs only
// the commit graph — but every caller here passes true, and the reason is worth
// stating because the cheaper option looks safe and is not.
//
// Filtering would be correct only where nothing downstream reads blob content
// from the local branch. No caller meets that bar: each one lands v1 as the
// repo's checkpoint store, and GitStore.List reads each checkpoint's
// metadata.json through a plain tree with no blob fetcher attached. Worse, the
// read path's recovery tier is keyed on the *ref* being missing, so once a
// filtered fetch lands the ref it never fires again — leaving `checkpoint list`
// permanently showing bare IDs with no prompt, date, or counts, recoverable only
// by explaining each checkpoint by ID.
//
